"""
    >>> base64encode('hello')
    'aGVsbG8='
    """
def base64encode(string: Any, layer: Any = 1) -> object {
    import from binascii { b2a_base64 }
    if (layer > 0) {
        return base64encode(
            b2a_base64(string.encode('UTF-8')).decode().replace("\n", ""), (layer - 1)
        );
    }
    return string;
}

"""
    Clamp value between min_val and max_val
