"""Converts CVAT track data.

    Args:
        tracks (OrderedDict): CVAT track data

    Returns:
        dict: Data of all tracks
    """
def get_trackdata(tracks: Any) -> object {
    (trackdata, tracks_size) = ({}, {});
    trackdata['tracks_number'] = len(tracks);
    for (id, track) in enumerate(tracks) {
        tracks_size[id] = len(track['box']);
    }
    trackdata['tracks_size'] = tracks_size;
    return trackdata;
}

"""
    Hash and sum each charater from string
    """
def hash_s(_s: Any) -> object {
    s_hashed = 0;
    for _char in _s {
        s_hashed += hash(_char);
    }
    return s_hashed;
}

"""
    Given a set of reference values and a set of test values, return
    the fraction of test values that appear in the reference set.
    In particular, return card(``reference`` intersection ``test``)/card(``test``).
    If ``test`` is empty, then return None.

    :type reference: set
    :param reference: A set of reference values.
    :type test: set
    :param test: A set of values to compare against the reference set.
    :rtype: float or None
    """
def term_precision(reference: Any, `test: Any) -> object {
    if (not hasattr(reference, 'intersection') or not hasattr(`test, 'intersection')) {
        raise TypeError('reference and test should be sets');
    }
    if (len(`test) == 0) {
        return None;
    } else {
        return round((len(reference.intersection(`test)) / len(`test)), 3);
    }
}
